package pre13mini;
public class MiniBank {public static void main(String[] args){Repository<Account> accounts=new Repository<>();accounts.saveAll(new Account("AC0001","Riya",5000),new Account("AC0002","Aman",2000),new Account("AC0003","Neha",9000));System.out.println("Find: "+accounts.findById("AC0002"));System.out.println("All accounts: "+accounts.findAll());Repository<Customer> customers=new Repository<>();customers.save(new Customer("CUST101","Riya"));System.out.println("Customers: "+customers.findAll());System.out.println("Average: "+Repository.average(new Integer[]{10,20,30}));}}
